const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');
const jwt = require('jsonwebtoken');

const app = express();
const PORT = 3001;

// Initialize Scalekit client
// Make sure to set SCALEKIT_ENV_URL and SCALEKIT_API_KEY environment variables
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENV_URL || 'https://api.scalekit.com',
  process.env.SCALEKIT_API_KEY || ''
);

app.get('/callback', async (req, res) => {
  try {
    // Extract code and state from query parameters
    const { code, state } = req.query;

    if (!code) {
      return res.status(400).json({
        error: 'Missing authorization code',
        message: 'The "code" query parameter is required'
      });
    }

    // Exchange the authorization code for tokens
    const authResponse = await scalekit.authenticateWithCode(
      code,
      'http://localhost:3001/callback'
    );

    // Decode the idToken to extract user information
    const decodedToken = jwt.decode(authResponse.idToken);

    // Extract email and name from the decoded token
    const userInfo = {
      email: decodedToken.email || null,
      name: decodedToken.name || null
    };

    // Return user details as JSON
    res.json({
      success: true,
      user: userInfo,
      state: state || null
    });

  } catch (error) {
    console.error('Error during authentication:', error);
    res.status(500).json({
      error: 'Authentication failed',
      message: error.message
    });
  }
});

// Start the server
app.listen(PORT, () => {
  console.log(`Scalekit callback server running on port ${PORT}`);
  console.log(`Callback URL: http://localhost:${PORT}/callback`);
});

